(x, y, t) => {
  const cx = 240, cy = 120;
  const sources = [
    [160 + Math.sin(t * 0.6) * 100, 80 + Math.cos(t * 0.4) * 50, 0.08, 2.0],
    [320 + Math.cos(t * 0.5) * 100, 160 + Math.sin(t * 0.7) * 50, 0.1, 1.7],
    [240 + Math.sin(t * 0.3 + 2) * 140, 120 + Math.cos(t * 0.5 + 1) * 90, 0.06, 2.3],
    [100 + Math.cos(t * 0.8 + 1) * 80, 180 + Math.sin(t * 0.6 + 3) * 60, 0.12, 1.5],
    [380 + Math.sin(t * 0.4 + 4) * 90, 60 + Math.cos(t * 0.9 + 2) * 70, 0.09, 1.9],
    [240 + Math.cos(t * 0.7 + 5) * 120, 200 + Math.sin(t * 0.35) * 80, 0.07, 2.6]
  ];
  let activator = 0, inhibitor = 0;
  for (let i = 0; i < sources.length; i++) {
    const [sx, sy, freq, spd] = sources[i];
    const d = Math.sqrt((x - sx) ** 2 + (y - sy) ** 2);
    const w = Math.sin(d * freq - t * spd);
    const w2 = Math.sin(d * freq * 0.5 + t * spd * 0.3);
    activator += w * (1.0 - i * 0.08);
    inhibitor += w2 * (0.6 + i * 0.05);
  }
  activator /= sources.length;
  inhibitor /= sources.length;
  const w4 = Math.sin(x * 0.05 + y * 0.03 + t * 0.8);
  const w5 = Math.sin(x * 0.03 - y * 0.05 + t * 1.1);
  const w6 = Math.sin((x + y) * 0.15 + t * 3) * 0.15;
  const w7 = Math.sin((x - y) * 0.12 - t * 2.5) * 0.15;
  const w8 = Math.sin(x * 0.02 + t * 0.5) * Math.cos(y * 0.025 - t * 0.7) * 0.3;
  const reaction = activator - inhibitor * 0.7 + (w4 + w5) * 0.3 + w6 + w7 + w8;
  const spot = Math.tanh(reaction * 2.5);
  const dist = Math.sqrt((x - cx) ** 2 + (y - cy) ** 2);
  const ang = Math.atan2(y - cy, x - cx);
  const warp = Math.sin(dist * 0.02 - t * 0.5) * 15;
  const wx = x + Math.cos(ang + t * 0.2) * warp;
  const wy = y + Math.sin(ang + t * 0.2) * warp;
  const radial = Math.sin(dist * 0.04 - t * 1.5);
  const angular = Math.sin(ang * 6 + t * 0.4);
  const spiral = Math.sin(ang * 3 - dist * 0.03 + t * 1.2) * 0.4;
  const pattern2 = Math.tanh((radial + angular * 0.5 + spiral) * 2);
  const dx = wx - cx, dy = wy - cy;
  const mesh1 = Math.sin(dx * 0.08 + t) * Math.sin(dy * 0.08 - t * 0.7);
  const mesh2 = Math.sin((dx + dy) * 0.06 + t * 1.3) * Math.cos((dx - dy) * 0.06 - t * 0.9);
  const pattern3 = Math.tanh((mesh1 + mesh2) * 1.8);
  const blend = spot * 0.45 + pattern2 * 0.3 + pattern3 * 0.25;
  const v = blend * 0.5 + 0.5;
  const pal = [
    [8, 12, 58], [15, 60, 110], [20, 130, 140], [60, 185, 155],
    [180, 200, 90], [225, 160, 55], [210, 90, 60], [140, 40, 70], [8, 12, 58]
  ];
  const idx = v * (pal.length - 1);
  const i = Math.min(idx | 0, pal.length - 2);
  const f = idx - i;
  const lum = 0.8 + Math.sin(reaction * Math.PI) * 0.2;
  const edge = 1.0 - Math.abs(blend) * 0.15;
  return [
    Math.min(255, (pal[i][0] + (pal[i + 1][0] - pal[i][0]) * f) * lum * edge) | 0,
    Math.min(255, (pal[i][1] + (pal[i + 1][1] - pal[i][1]) * f) * lum * edge) | 0,
    Math.min(255, (pal[i][2] + (pal[i + 1][2] - pal[i][2]) * f) * lum * edge) | 0
  ];
}
